Q: Input in a prompt for an answer A: <p>For fun and maybe some learning: here's an idea (without a prompt)</p>
<p>You may want to learn about:</p>
<ul>
<li><a href="https://javascript.info/event-delegation" rel="nofollow noreferrer">Event delegation</a></li>
<li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions" rel="nofollow noreferrer">Regular expressions</a></li>
<li><a href="https://developer.mozilla.org/en-US/docs/Web/API/Document/querySelector" rel="nofollow noreferrer">The document.querySelector method</a></li>
<li><a href="https://developer.mozilla.org/en-US/docs/Web/API/Element/insertAdjacentHTML" rel="nofollow noreferrer">The insertAdjacentHTML method</a></li>
</ul>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// regular expression to test answer values
const answers = [
  /^(shoes|pumps|high heels)$/i,
  /^(lighthouse|clouds)$/i,
  /^(ship|boat|sea)$/i,
];

// add an Enter-hander (event delegation)
document.addEventListener(`keyup`, handle);

// focus the first input field
document.querySelector(`input[data-image="0"]`).focus();

// handle input ('keyup')
function handle(evt) {
  if (evt.key === `Enter`) {
    // get the inputted value
    const field = evt.target;
    const value = field.value.trim();
    const regex = answers[field.dataset.image];
    // retrieve the feedback div (div.result)
    const feedback = field.closest(`.q`).querySelector(`.result`);

    // if the test succeeds report it and move
    // to the next question
    if (regex.test(value)) {
      feedback.textContent = `That's right!`;
      field.setAttribute(`disabled`, `disabled`);
      const nextField = field.closest(`.container`)
        .querySelector(`[data-active="false"]`);

      if (nextField) {
        nextField.dataset.active = true;
        nextField.scrollIntoView();
        nextField.querySelector(`input`).focus();
      }

      return !nextField 
        ? success() : true;
    }

    feedback.textContent = `Try again ...`;
    field.value = ``;

    return field.focus();
  }
}


function success() {
  // add a header after all questions are answered
  const container = document.querySelector(`.container`);
  container.insertAdjacentHTML(`afterbegin`, `&lt;h3&gt;All done, congrats!&lt;/h3&gt;`)
  container.scrollIntoView();
}</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>body {
  margin: 1rem;

  .container {
    div[data-active] {
      margin: 0.5em 0;
      vertical-align: top;

    img {
      margin-right: 1em;
      display: inline-block;
      vertical-align: top;
    }

    .q {
      display: inline-block;
    }

    &amp;[data-active="false"] {
      display: none;
    }
  }
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div class="container"&gt;
  &lt;div&gt;Tell us what you see (press enter when done)&lt;/div&gt;
  &lt;div data-active="true"&gt;
    &lt;img src="//picsum.photos/id/21/150/100"&gt;
    &lt;div class="q"&gt;
      &lt;div class="result"&gt;&lt;/div&gt;
      &lt;input data-image="0" placeholder="What do you see?"&gt;
    &lt;/div&gt;  
  &lt;/div&gt;
  &lt;div data-active="false"&gt;
    &lt;img src="//picsum.photos/id/58/150/100"&gt;
    &lt;div class="q"&gt;
      &lt;div class="result"&gt;&lt;/div&gt;
      &lt;input data-image="1" placeholder="What do you see?"&gt;
    &lt;/div&gt;
  &lt;/div&gt;
  &lt;div data-active="false"&gt;
    &lt;img src="//picsum.photos/id/124/150/100"&gt;
    &lt;div class="q"&gt;
      &lt;div class="result"&gt;&lt;/div&gt;
      &lt;input data-image="2" placeholder="What do you see?"&gt;
    &lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;</code></pre>
